import json
import re


def extract_rule(text):
    blocks = re.findall(r'```(?:json)?\s*(\{.*?\})\s*```', text, re.S | re.I)
    for block in reversed(blocks):
        try:
            payload = json.loads(block)
        except json.JSONDecodeError:
            continue
        rule = payload.get('rule') if isinstance(payload, dict) else None
        if isinstance(rule, str) and rule.strip():
            return rule.strip()
    raise ValueError('no usable rule block')


def rule_is_complete(rule):
    if not isinstance(rule, str):
        return False
    text = rule.lower()
    has_a = 'a' in text
    has_b = 'b' in text
    has_condition = any(word in text for word in ('偶数', '奇数', '大于', '小于', '等于', 'even', 'odd', 'greater', 'less', 'equal'))
    return has_a and has_b and has_condition
